import{_ as e,a,c as n,b as l}from"./chunks/framework.b9WMfGr4.js";const g=JSON.parse('{"title":"07-结构化卡片与媒体组件","description":"深入解析文件目录树卡片 FileTreeCard、图片说明图解卡片 ImageFigure、文章封面组件与双链悬浮预览卡片设计。","frontmatter":{"title":"07-结构化卡片与媒体组件","date":"2026-10-01T00:00:00.000Z","author":"道林学长","description":"深入解析文件目录树卡片 FileTreeCard、图片说明图解卡片 ImageFigure、文章封面组件与双链悬浮预览卡片设计。","tags":["组件设计","结构化卡片"]},"headers":[],"relativePath":"posts/0-博客指南/博客的组件设计/07-结构化卡片与媒体组件.md","filePath":"posts/0-博客指南/博客的组件设计/07-结构化卡片与媒体组件.md"}'),r={name:"posts/0-博客指南/博客的组件设计/07-结构化卡片与媒体组件.md"};function i(o,s,t,p,c,d){return a(),n("div",null,[...s[0]||(s[0]=[l(`<h1 class="hidden-duplicate-h1" style="display:none !important;" id="_07-结构化卡片与媒体组件" tabindex="-1">07-结构化卡片与媒体组件 <a class="header-anchor" href="#_07-结构化卡片与媒体组件" aria-label="Permalink to &quot;07-结构化卡片与媒体组件&quot;">​</a></h1><div class="post-cover-wrapper"><img src="https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&amp;fit=crop&amp;w=1200&amp;q=80" alt="cover" class="post-cover-image" referrerpolicy="no-referrer" loading="lazy"></div><p>技术文档不仅包含文本与代码，还需要承载工程文件拓扑、关键截图阐释以及视觉封面等复合媒体。博客设计了一组语义丰富的高表现力结构化卡片组件，使文档展示更加专业规整。</p><h2 id="_1-结构化文件树卡片-filetreecard" tabindex="-1">1. 结构化文件树卡片 FileTreeCard <a class="header-anchor" href="#_1-结构化文件树卡片-filetreecard" aria-label="Permalink to &quot;1. 结构化文件树卡片 FileTreeCard&quot;">​</a></h2><p>针对技术教程中必不可少的工程目录讲解，编译器将 <code>filetree</code> 代码块转化为带有视觉图标与排版引导线的结构化卡片：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><button class="collapse-btn" title="折叠代码" aria-label="折叠代码"><svg class="collapse-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></button><span class="lang">Text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>┌─ [目录结构] ─────────────────────────────────────────────────── [复制目录树] ─┐</span></span>
<span class="line"><span>│  📁 src/                                                                       │</span></span>
<span class="line"><span>│  │  📁 controllers/                # 接口路由控制器                             │</span></span>
<span class="line"><span>│  │  📁 services/                   # 核心业务服务                               │</span></span>
<span class="line"><span>│  │  │  📄 auth.service.ts          # 认证逻辑与会话管理                          │</span></span>
<span class="line"><span>│  │  └──📄 user.service.ts                                                      │</span></span>
<span class="line"><span>│  └── 📄 main.ts                    # 应用启动入口                               │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div><div class="code-collapsed-indicator"><span class="code-collapsed-text">已折叠代码，点击展开</span><svg class="expand-icon" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></div></div><ul><li><strong>智能图标匹配</strong>：以斜杠结尾的条目自动渲染文件夹专属 SVG 图标，普通文件名自动匹配文本文件图标。</li><li><strong>注释自动右对齐隔离</strong>：在文件名后使用 <code>#</code> 或 <code>//</code> 声明的解释说明，渲染器会自动将其分离并在行末右对齐展示，杜绝说明文字与长文件名粘连混淆。</li><li><strong>纯文本一键复制</strong>：卡片右上角提供复制按钮，点击可将原始格式化目录树文本提取至剪贴板，方便读者直接用于本地工程搭建。</li></ul><h2 id="_2-图片内容说明图解卡片-imagefigure" tabindex="-1">2. 图片内容说明图解卡片 ImageFigure <a class="header-anchor" href="#_2-图片内容说明图解卡片-imagefigure" aria-label="Permalink to &quot;2. 图片内容说明图解卡片 ImageFigure&quot;">​</a></h2><p>为了让二进制图片的信息对外透明化并支持全站全文检索，系统将携带 <code>desc:</code> 或 HTML 注释的图片升级为图解说明卡片：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><button class="collapse-btn" title="折叠代码" aria-label="折叠代码"><svg class="collapse-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></button><span class="lang">Text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                              [ 本地或外链架构插图 ]                              │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>┌─ [图片内容解析说明] ───────────────────────────────────────────── [复制说明] ─┐</span></span>
<span class="line"><span>│ 本图详细阐述了客户端发起 HTTP 请求到 API 网关鉴权，再经由核心业务服务调用 Redis  │</span></span>
<span class="line"><span>│ 缓存与持久化落盘至数据库的完整数据流向。                                         │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div><div class="code-collapsed-indicator"><span class="code-collapsed-text">已折叠代码，点击展开</span><svg class="expand-icon" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></div></div><ul><li><strong>语义化 HTML5 标记</strong>：卡片整体由 <code>&lt;figure class=&quot;image-figure-card&quot;&gt;</code> 与 <code>&lt;figcaption&gt;</code> 语义标签包裹，符合现代 Web 标准。</li><li><strong>文字化沉淀与一键复制</strong>：架构图解的详细解析文字在卡片底部独立成区，支持读者一键复制提取要点。</li><li><strong>索引加权搜索</strong>：说明内容完全纳入全局搜索索引，使得读者可以通过文字检索直达对应图解。</li></ul><h2 id="_3-文章封面大图组件-coverwrapper" tabindex="-1">3. 文章封面大图组件 CoverWrapper <a class="header-anchor" href="#_3-文章封面大图组件-coverwrapper" aria-label="Permalink to &quot;3. 文章封面大图组件 CoverWrapper&quot;">​</a></h2><p>为了在各端编辑器与博客发布页面之间取得统一的沉浸式视觉体验，系统设计了封面组件：</p><ul><li><strong>标记语义识别</strong>：当图片的替代文本 alt 声明为 <code>cover</code>、<code>封面</code> 或 <code>banner</code> 时，编译器将其由普通段落升级为 <code>&lt;div class=&quot;post-cover-wrapper&quot;&gt;</code> 专用封面容器。</li><li><strong>视觉层级重组</strong>：页面布局将封面置于文章标题、作者与元数据标签下方，并在正文首段之前展开，形成开阔典雅的杂志式排版质感。</li></ul><h2 id="_4-双向链接悬浮预览卡片" tabindex="-1">4. 双向链接悬浮预览卡片 <a class="header-anchor" href="#_4-双向链接悬浮预览卡片" aria-label="Permalink to &quot;4. 双向链接悬浮预览卡片&quot;">​</a></h2><p>当读者在阅读长文遇到内链与双向链接时，悬浮预览卡片提供免跳转阅读体验：</p><ul><li><strong>视口边缘自适应探测</strong>：鼠标悬停在内链上方数十毫秒后，预览浮层自动计算边界，防止超出屏幕边缘或被遮挡。</li><li><strong>元数据上下文透传</strong>：浮动视窗内即时渲染目标文章的分类层级、发布时间、标题、正文摘要与预计阅读时间，让知识探索无缝穿透。</li></ul>`,17)])])}const b=e(r,[["render",i]]);export{g as __pageData,b as default};
